;438:
;439:	// The 1.02 client doesn't show the force selection menu if ANY force power is disabled. And the basejk 1.02 server sets saber attack to level 3,
;440:	// saber defense to level 3 and force jump to level 1, if ANY force power is disabled. This leads to some differences in g_forcePowerDisable
;441:	// behaviour between 1.02 and 1.03+. For instance disabling all powers except jump, saber attack and saber defense on 1.02 behaves the same as
;442:	// disabling all force powers on 1.03+. To stay compatible with existing configs mvsdk is going to handle g_forcePowerDisable like 1.02, when
;443:	// loaded in 1.02 mode and mv_forcePowerDisableMode is set. By disabling this cvar 1.03+ behaviour is going to be enabled in 1.02 mode, but
;444:	// base clients might have disadvantages, cause their ui doesn't allow them to assign force jump points, even when force jump is enabled.
;445:	// This cvar only has an effect when the startversion is 1.02.
;446:	{ &g_mv_forcePowerDisableMode, "mv_forcePowerDisableMode", "1", CVAR_ARCHIVE, 0, qfalse },
;447:
;448:	// g_submodelWorkaround was technically just setting a flag for mvsdk clients to apply the clientside workaround
;449:	// The cvar might seem more appropriate on cgame, but defaulting it to "0" on the client would make the workaround hardly usable
;450:	// and defaulting it to "1" on the the client might lead to mappers not realising they exceeded basejk limits when testing their maps.
;451:	// So we have a cvar in the game module to let servers enable the clientside workaround for bigger maps, defaulting to "0".
;452:	// Clients supporting the workaround are going to inform the server about it in their userinfo, no matter what this cvar is set to.
